$window=Wait-MediaWindow;$watch=[Diagnostics.Stopwatch]::StartNew();do{Start-Sleep -Milliseconds 100;$source=([Windows.Automation.ValuePattern](Media-Item '101').GetCurrentPattern([Windows.Automation.ValuePattern]::Pattern)).Current.Value;$message=(Media-Item '108').Current.Name}while(($source-or$message-notmatch'Browser source unavailable')-and$watch.ElapsedMilliseconds-lt5000)
$new=@(Get-ChildItem ($env:APPDATA+'\DybergCo\Koett\data\Media Transcripts') -File|Where-Object {$_.Name-notin$global:M5PrivateBefore.files});$status=(Run-MediaCli 'status').stdout|ConvertFrom-Json
@{passed=($source-eq''-and$message-match'Browser source unavailable'-and$new.Count-eq0-and-not$status.media_active);before=$global:M5PrivateBefore;source=$source;message=$message;new_records=$new.Count;status=$status;focus=Get-LabFocus;step=Media-Step 'private-source-omitted';artifact=Get-LabArtifact}
